{
  "steps": [
    {
      "step_id": 1,
      "time": "08:00",
      "role": "市气象局",
      "action": "灾害预警",
      "description": "气象部门率先发布强降雨预警信息，预计未来24小时局地有大暴雨，地质灾害气象风险等级高，提醒相关区县和部门加强防范。",
      "resources": []
    },
    {
      "step_id": 2,
      "time": "08:05",
      "role": "市资源规划局",
      "action": "灾害预警",
      "description": "市资源规划局联合市气象局发布地质灾害气象风险预警（橙色），要求各区县资源规划部门加强巡查排查，群测群防员到岗到位，做好受威胁群众转移准备。",
      "resources": []
    },
    {
      "step_id": 3,
      "time": "08:10",
      "role": "社区/基层",
      "action": "险情巡查",
      "description": "蓝田县普化镇周董村群测群防员对地质灾害隐患点开展巡查，发现滑坡体后缘裂缝明显加宽、前缘出现渗水冒浑，险情加剧，立即上报镇政府并通知周边群众注意防范。",
      "resources": []
    },
    {
      "step_id": 4,
      "time": "08:15",
      "role": "社区/基层",
      "action": "灾情上报",
      "description": "周董村监测员发现险情后第一时间向普化镇政府报告，镇政府核实后迅速上报蓝田县应急管理局和县资源规划局，报告内容包括灾害发生时间、地点、类型、规模及发展趋势等。",
      "resources": []
    },
    {
      "step_id": 5,
      "time": "08:20",
      "role": "市资源规划局",
      "action": "灾情上报",
      "description": "市资源规划局接到蓝田县报告后，与市应急局相互通报信息并开展会商，按相关规定向省自然资源厅、省应急厅、市委市政府报告灾情，同时对灾情进行核实，及时续报。",
      "resources": []
    },
    {
      "step_id": 6,
      "time": "08:25",
      "role": "市应急局",
      "action": "会商研判",
      "description": "市应急局组织市资源规划局、市气象局、市水利局等部门开展联合会商研判，分析滑坡发展趋势、降雨影响范围及可能造成的危害，提出启动应急响应的建议。",
      "resources": []
    },
    {
      "step_id": 7,
      "time": "08:30",
      "role": "应急指挥部",
      "action": "启动响应",
      "description": "西安市立即启动《西安市突发地质灾害应急预案》Ⅱ级响应，成立市突发地质灾害应急指挥部和现场指挥部，命令市防灾减灾救灾工作委员会各成员单位按照预案职责指导蓝田县开展人员疏散安置、应急救援、交通疏导、警戒防控等工作。",
      "resources": []
    },
    {
      "step_id": 8,
      "time": "08:35",
      "role": "应急指挥部",
      "action": "统一指挥",
      "description": "市突发地质灾害应急指挥部统一指挥协调各工作组行动，下设综合协调组、抢险救援组、医疗救护组、交通管制组、后勤保障和善后安置组、调查监测组、宣传报道组等，明确各组职责分工。",
      "resources": []
    },
    {
      "step_id": 9,
      "time": "08:40",
      "role": "应急指挥部",
      "action": "应急队伍集结",
      "description": "命令市消防救援支队、中国安能二局厦门分公司、厦门警备区、武警厦门支队等应急队伍迅速集结，携带生命探测仪、破拆工具、挖掘机等装备赶赴灾区现场。",
      "resources": [
        {"resource_type": "生命探测仪", "quantity": 3},
        {"resource_type": "破拆工具", "quantity": 5},
        {"resource_type": "挖掘机", "quantity": 2}
      ]
    },
    {
      "step_id": 10,
      "time": "08:45",
      "role": "交通管制组",
      "action": "交通管制",
      "description": "警戒防控组对受灾区域的道路入口实施临时交通管制措施，严禁无关车辆及人员进入，保障救援通道畅通。",
      "resources": [
        {"resource_type": "运输车辆", "quantity": 4}
      ]
    },
    {
      "step_id": 11,
      "time": "08:50",
      "role": "社区/基层",
      "action": "危险区划定",
      "description": "灾害发生地政府及所属部门、镇（街）和村（居）及有关责任单位立即派人赶赴现场开展调查，根据滑坡体规模和影响范围划定危险区，设立警示标志，封锁进出道路。",
      "resources": []
    },
    {
      "step_id": 12,
      "time": "08:55",
      "role": "社区/基层",
      "action": "人员转移引导",
      "description": "村干部、监测员带领志愿者，通过敲锣发出撤离信号和广播通知受威胁群众，按照预定的安全撤离路线，引导大家有序转移到安全区域。在转移过程中，特别安排专人照顾老弱病残孕等特殊人群，确保每个人的安全。",
      "resources": []
    },
    {
      "step_id": 13,
      "time": "09:05",
      "role": "疏散引导组",
      "action": "人员转移",
      "description": "疏散引导组组织受威胁群众按照预定路线有序转移至临时安置点，逐户排查确保不漏一人，特别关注老弱病残孕等特殊人群的转移安全。",
      "resources": [
        {"resource_type": "运输车辆", "quantity": 6}
      ]
    },
    {
      "step_id": 14,
      "time": "09:15",
      "role": "后勤保障和善后安置组",
      "action": "安置点开放",
      "description": "后勤保障和善后安置组在蓝田县普化镇周董村安全区域搭建临时安置点，开放安置场所，做好接收受灾群众的各项准备工作。",
      "resources": [
        {"resource_type": "帐篷", "quantity": 20}
      ]
    },
    {
      "step_id": 15,
      "time": "09:20",
      "role": "社区/基层",
